//! Pre-rasterized UI fonts (generated by `tools/gen_font.py` from Inter, OFL-1.1).

use std::sync::LazyLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FontId {
    Ui = 0,
    UiBold = 1,
    Title = 2,
}

pub struct Glyph {
    pub advance: u8,
    pub width: u8,
    pub alpha: Vec<u8>,
}

pub struct Font {
    pub line_height: u16,
    pub ascent: u16,
    pub glyphs: Vec<Glyph>,
}

impl Font {
    pub fn glyph(&self, c: char) -> &Glyph {
        let code = c as u32;
        let idx = if (32..127).contains(&code) { code - 32 } else { b'?' as u32 - 32 };
        &self.glyphs[idx as usize]
    }

    pub fn measure(&self, s: &str) -> i32 {
        s.chars().map(|c| self.glyph(c).advance as i32).sum()
    }
}

static DATA: &[u8] = include_bytes!("../assets/fonts.bin");

pub static FONTS: LazyLock<Vec<Font>> = LazyLock::new(|| {
    let mut p = 0usize;
    let rd16 = |p: &mut usize| {
        let v = u16::from_le_bytes([DATA[*p], DATA[*p + 1]]);
        *p += 2;
        v
    };
    let count = u32::from_le_bytes([DATA[0], DATA[1], DATA[2], DATA[3]]);
    p += 4;
    let mut fonts = Vec::new();
    for _ in 0..count {
        let line_height = rd16(&mut p);
        let ascent = rd16(&mut p);
        let mut glyphs = Vec::new();
        for _ in 32..127 {
            let advance = DATA[p];
            let width = DATA[p + 1];
            p += 2;
            let n = width as usize * line_height as usize;
            glyphs.push(Glyph { advance, width, alpha: DATA[p..p + n].to_vec() });
            p += n;
        }
        fonts.push(Font { line_height, ascent, glyphs });
    }
    fonts
});

pub fn line_height(id: FontId) -> i32 {
    FONTS[id as usize].line_height as i32
}
